import{_ as a,a as t,c as r,k as n}from"./chunks/framework.Dwx0C2I0.js";const p=JSON.parse('{"title":"Site notes","description":"How Keith Williams’s journal and Ordo Knowledge Lab handle sharing, search, contact, artwork, sources, and requests to reuse the work.","frontmatter":{"title":"Site notes","description":"How Keith Williams’s journal and Ordo Knowledge Lab handle sharing, search, contact, artwork, sources, and requests to reuse the work.","teaser":"What happens when you read, share, or reuse something from this site, and how to reach Keith about a correction or accessibility problem."},"headers":[],"relativePath":"site-notes.md","filePath":"site-notes.md"}'),i={name:"site-notes.md"};function o(s,e,d,h,l,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="site-notes" tabindex="-1">Site notes <a class="header-anchor" href="#site-notes" aria-label="Permalink to &quot;Site notes&quot;">​</a></h1><p>I publish this journal and Ordo Knowledge Lab as part of my work as an educator and software builder. The views here are my own. If an article contains an error, an image needs a better description, or a page is difficult to use, send me the page link and tell me what you encountered. <a href="https://people.njit.edu/profile/kwilliam" target="_blank" rel="noreferrer">Contact Keith through NJIT</a></p><h2 id="reading-and-searching" tabindex="-1">Reading and searching <a class="header-anchor" href="#reading-and-searching" aria-label="Permalink to &quot;Reading and searching&quot;">​</a></h2><p>GitHub Pages hosts both publications and logs visitors’ IP addresses for security. I haven’t added advertising pixels or visitor analytics to these pages. The Knowledge Lab searches a downloaded index in your browser. It keeps the current search in tab-session storage and can remember display preferences on your device. Reading an example or a prompt here doesn’t send it to an AI service. <a href="https://docs.github.com/en/pages/getting-started-with-github-pages/what-is-github-pages#data-collection" target="_blank" rel="noreferrer">GitHub Pages data collection</a> · <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">GitHub privacy statement</a></p><h2 id="sharing-and-getting-in-touch" tabindex="-1">Sharing and getting in touch <a class="header-anchor" href="#sharing-and-getting-in-touch" aria-label="Permalink to &quot;Sharing and getting in touch&quot;">​</a></h2><p><strong>Copy link</strong> copies the public page address. <strong>Share on LinkedIn</strong> opens LinkedIn with that address so you can review your post. On supported devices, the additional sharing option opens your device’s share menu. You choose the destination. <a href="https://www.linkedin.com/legal/privacy-policy" target="_blank" rel="noreferrer">LinkedIn privacy policy</a></p><p>A project question posted on GitHub is public. For a private inquiry, an accessibility problem that includes personal information, or a question about student work, use my faculty contact. Enrolled students can use their usual private course channel. <a href="https://people.njit.edu/profile/kwilliam" target="_blank" rel="noreferrer">NJIT faculty contact</a></p><h2 id="artwork-audio-and-sources" tabindex="-1">Artwork, audio, and sources <a class="header-anchor" href="#artwork-audio-and-sources" aria-label="Permalink to &quot;Artwork, audio, and sources&quot;">​</a></h2><p>I use AI-generated illustrations to explain ideas. The author portrait is an AI-assisted adaptation of a photograph of me. The optional audio introduction uses a synthetic voice, and its transcript is next to the player. Technical diagrams, references, and links to original materials appear with the work they support.</p><h2 id="type-and-lettering" tabindex="-1">Type and lettering <a class="header-anchor" href="#type-and-lettering" aria-label="Permalink to &quot;Type and lettering&quot;">​</a></h2><p>This journal pairs Source Serif 4 for reading with Source Sans 3 for navigation. Frank Grießhammer designed the serif family and Paul D. Hunt designed its sans companion. Both typefaces load from this site. The GitHub and LinkedIn symbols come from Font Awesome Free by Fonticons and link to my public profiles. <a href="/type/source-serif-4-OFL.txt">Source Serif license</a> · <a href="/type/source-sans-3-OFL.txt">Source Sans license</a> · <a href="/icons/font-awesome-license.txt">Icon credits and license</a></p><h2 id="teaching-and-reuse" tabindex="-1">Teaching and reuse <a class="header-anchor" href="#teaching-and-reuse" aria-label="Permalink to &quot;Teaching and reuse&quot;">​</a></h2><p>The teacher Studio includes directions for adapting an assignment and identifies which files to give students. For software, images, and third-party readings, check the terms attached to the original work. If you want to republish an article or use an illustration and the terms are unclear, send me the page and a short description of your intended use. <a href="https://keithwilliams.org/downloads/AI-Studio-Starter.zip" target="_blank" rel="noreferrer">Teacher Studio</a> · <a href="https://people.njit.edu/profile/kwilliam" target="_blank" rel="noreferrer">Contact Keith</a></p>',13)])])}const g=a(i,[["render",o]]);export{p as __pageData,g as default};
